#!/data/data/com.termux/files/usr/bin/bash
# SekexBot one-file installer for Android (Termux).  Version 2.42.0
#
#   1. Save this file in the phone's Download folder.
#   2. Optional: fill in sekexbot-setup.conf and put it in Download too (your keys, daily limit, START_TRADING=yes).
#   3. Optional, to carry over the learning memory and journal from another phone or PC: a folder named
#      SekexBot_data in Download that holds that copy's  data  folder and  .env  file.
#   4. In Termux run:
#        termux-setup-storage; until [ -r /sdcard/Download/SekexBot_Setup.sh ]; do sleep 2; done; bash /sdcard/Download/SekexBot_Setup.sh
set -e
HERE="$(cd "$(dirname "$0")" && pwd)"
case "$HERE" in /sdcard/*|/storage/*|*/storage/downloads*) ;; esac
WORK="$HOME/.sekexbot_setup_tmp"
rm -rf "$WORK"; mkdir -p "$WORK"
echo
echo "  SekexBot 2.42.0 - unpacking the installer..."
sed -n '/^__SEKEX_PAYLOAD__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xz -C "$WORK" || { echo "XX The file looks damaged. Download it again."; exit 1; }
[ -f "$WORK/SekexBot_Android/install.sh" ] || { echo "XX Unpacking failed (install.sh missing)."; exit 1; }
export SEKEX_SETUP_DIR="$HERE"
[ -d /sdcard/Download ] && [ ! -f "$HERE/sekexbot-setup.conf" ] && export SEKEX_SETUP_DIR="/sdcard/Download"
bash "$WORK/SekexBot_Android/install.sh"
rc=$?
rm -rf "$WORK"
exit $rc
